CREATE FUNCTION public.fi_import_farm(p_org uuid,p_farm uuid,p_name text,p_location text,p_fields jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE farm uuid; item jsonb; fid uuid; v integer; g extensions.geometry; other extensions.geometry; shapes extensions.geometry[]:=ARRAY[]::extensions.geometry[]; codes text[]:=ARRAY[]::text[]; matches uuid[]:=ARRAY[]::uuid[]; employee text; BEGIN IF auth.uid() IS NULL OR NOT comm_manager(p_org) THEN RAISE EXCEPTION 'Organization manager required'; END IF; IF jsonb_array_length(p_fields)<1 OR jsonb_array_length(p_fields)>200 OR length(trim(p_name))<2 THEN RAISE EXCEPTION 'Invalid farm fields'; END IF; IF p_farm IS NOT NULL THEN SELECT id INTO farm FROM fi_farms WHERE id=p_farm AND org_id=p_org AND NOT demo FOR UPDATE; IF farm IS NULL THEN RAISE EXCEPTION 'Farm unavailable'; END IF; ELSE INSERT INTO fi_farms(org_id,name,location,created_by) VALUES(p_org,p_name,p_location,auth.uid()) RETURNING id INTO farm; END IF; FOR item IN SELECT * FROM jsonb_array_elements(p_fields) LOOP IF length(trim(item->>'name'))=0 OR length(trim(item->>'code'))=0 OR (item->>'code')=ANY(codes) THEN RAISE EXCEPTION 'Missing names or duplicate identifiers'; END IF; codes:=array_append(codes,item->>'code'); g:=extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON((item->'geometry')::text),4326); IF NOT extensions.ST_IsValid(g) OR extensions.ST_IsEmpty(g) OR extensions.ST_GeometryType(g) NOT IN ('ST_Polygon','ST_MultiPolygon') THEN RAISE EXCEPTION 'Invalid polygon'; END IF; FOREACH other IN ARRAY shapes LOOP IF extensions.ST_Area(extensions.ST_Intersection(g,other)::extensions.geography)>0.1 THEN RAISE EXCEPTION 'Overlapping fields'; END IF; END LOOP; shapes:=array_append(shapes,g); IF item->>'matchId' IS NOT NULL THEN fid:=(item->>'matchId')::uuid; IF fid=ANY(matches) OR NOT EXISTS(SELECT 1 FROM fi_fields WHERE id=fid AND farm_id=farm) THEN RAISE EXCEPTION 'Invalid or duplicate field match'; END IF; matches:=array_append(matches,fid); UPDATE fi_fields SET name=item->>'name',crop=COALESCE(item->>'crop',''),active=true WHERE id=fid; ELSE INSERT INTO fi_fields(farm_id,code,name,crop) VALUES(farm,item->>'code',item->>'name',COALESCE(item->>'crop','')) RETURNING id INTO fid; END IF; SELECT COALESCE(max(version),0)+1 INTO v FROM fi_boundaries WHERE field_id=fid; INSERT INTO fi_boundaries(field_id,version,geometry,created_by) VALUES(fid,v,item->'geometry',auth.uid()); DELETE FROM fi_assignments WHERE field_id=fid; FOR employee IN SELECT jsonb_array_elements_text(COALESCE(item->'users','[]'::jsonb)) LOOP IF NOT EXISTS(SELECT 1 FROM comm_org_members WHERE org_id=p_org AND user_id=employee::uuid) THEN RAISE EXCEPTION 'Employee is not an organization member'; END IF; INSERT INTO fi_assignments(field_id,user_id) VALUES(fid,employee::uuid) ON CONFLICT DO NOTHING; END LOOP; END LOOP; UPDATE fi_farms SET name=p_name,location=p_location WHERE id=farm; RETURN farm; END $$;
REVOKE ALL ON FUNCTION public.fi_import_farm(uuid,uuid,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fi_import_farm(uuid,uuid,text,text,jsonb) TO authenticated;
CREATE POLICY fi_evidence_owner_upload ON storage.objects FOR SELECT TO authenticated USING(bucket_id='field-evidence' AND (storage.foldername(name))[2]=auth.uid()::text AND public.fi_report_access(((storage.foldername(name))[1])::uuid));